import unittest
from config_options import merge_options

class OptionsTests(unittest.TestCase):
    def test_ordinary_override(self):
        self.assertEqual(merge_options({'port': 80}, {'port': 443}), {'port': 443})
    def test_explicit_false(self):
        self.assertEqual(merge_options({'enabled': True}, {'enabled': False}), {'enabled': False})
    def test_none_is_missing(self):
        self.assertEqual(merge_options({'mode': 'safe'}, {'mode': None}), {'mode': 'safe'})

