import unittest
from query_params import add_query

class QueryTests(unittest.TestCase):
    def test_simple(self):
        self.assertEqual(add_query('https://example.test/path', {'page': 2}), 'https://example.test/path?page=2')
    def test_fragment(self):
        self.assertEqual(add_query('https://example.test/path#part', {'page': 2}), 'https://example.test/path?page=2#part')
